#!/usr/bin/env bash

#------------------------------------------------------------------------------
# test_park.sh - tests for park.sh (stubbed gh and board script, no network).
# usage: test_park.sh        (exit code 0 = all passed)
#------------------------------------------------------------------------------
set -uo pipefail

SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
# shellcheck disable=SC2034  # used by run_script in testing-lib.sh
SCRIPT_UNDER_TEST=${PARK_UNDER_TEST:-$SCRIPT_DIR/park.sh}
# shellcheck disable=SC1091  # testing-lib.sh belongs to the project-board skill
source "$SCRIPT_DIR/../../project-board/scripts/testing-lib.sh"
handle_test_help "$@"

STUB_DIR="$TEST_TMP/stub"
mkdir -p "$STUB_DIR" "$TEST_TMP/bin"
# shellcheck disable=SC2016  # the texts are scripts for the stubs, expanded when they run
printf '%s\n' '#!/usr/bin/env bash' 'echo "gh $*" >> "$STUB_DIR/calls.log"' \
    'if [ "$1 $2" = "issue comment" ]; then cat > "$STUB_DIR/comment.txt"; fi' \
    '[ -f "$STUB_DIR/gh-fails" ] && { echo "gh: boom" >&2; exit 1; }; exit 0' > "$TEST_TMP/bin/gh"
# shellcheck disable=SC2016
printf '%s\n' '#!/usr/bin/env bash' 'echo "board $*" >> "$STUB_DIR/calls.log"' > "$STUB_DIR/board.sh"
chmod +x "$TEST_TMP/bin/gh" "$STUB_DIR/board.sh"
export STUB_DIR GH_REPO="o/r" PATH="$TEST_TMP/bin:$PATH" BOARD_SCRIPT="$STUB_DIR/board.sh"

# Run the whole suite with the current shell.
run_suite() {
    rm -f "$STUB_DIR/calls.log" "$STUB_DIR/comment.txt" "$STUB_DIR/gh-fails"
    run_script 7 "the same action ran twice without a change"
    check_that "parking succeeds" [ "$RC" -eq 0 ]
    check_that "the label is created if missing" grep -q "^gh label create needs-info --force" "$STUB_DIR/calls.log"
    check_that "the label is added to the issue" grep -q "^gh issue edit 7 --add-label needs-info" "$STUB_DIR/calls.log"
    check_that "the comment starts with the AI line" [ "$(head -1 "$STUB_DIR/comment.txt")" = "> *This was generated by AI (orchestrator).*" ]
    check_that "the comment carries the reason" grep -q "twice without a change" "$STUB_DIR/comment.txt"
    check_that "the issue goes back to Triage (which clears the claim)" grep -q "^board move 7 Triage" "$STUB_DIR/calls.log"
    check_that "the move comes last" [ "$(tail -1 "$STUB_DIR/calls.log")" = "board move 7 Triage" ]

    rm -f "$STUB_DIR/calls.log"
    touch "$STUB_DIR/gh-fails"
    run_script 7 "reason"
    check_that "a failing gh call stops it with an error" [ "$RC" -ne 0 ]
    check_that "the issue is not moved when the label failed" [ "$(grep -c '^board' "$STUB_DIR/calls.log")" = "0" ]
    rm -f "$STUB_DIR/gh-fails"

    run_script
    check_that "no arguments is a usage error" [ "$RC" -eq 1 ]
    run_script x "reason"
    check_that "a non-numeric issue is refused" [ "$RC" -eq 1 ]
    run_script 7 ""
    check_that "an empty reason is refused" [ "$RC" -eq 1 ]
    run_script --help
    check_that "--help prints the usage and exits 0" [ "$RC" -eq 0 ]
}

for_each_shell run_suite
finish
